import type { IsoTimestamp, OrgId, UserId } from "./common";

/** `read` tokens act as a viewer; `write` tokens act with the member's role. */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the service layer exposes it. Never carries the
 * secret or its hash — the secret is returned exactly once, on creation.
 */
export interface ApiToken {
  id: string;
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  /** First 12 characters of the secret, for recognising a token in the UI. */
  prefix: string;
  expiresAt: IsoTimestamp;
  lastUsedAt: IsoTimestamp | null;
  revokedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
}
EOF
