/**
 * Personal API token rows. Only the hash of a secret is ever stored; lookups by
 * secret go through `findTokenByHash`.
 */
import { and, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { ApiTokenRow } from "@/server/db";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  prefix: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
}

function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: brandStampOrNull(row.lastUsedAt),
    revokedAt: brandStampOrNull(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

export async function insertApiToken(input: NewApiToken): Promise<ApiToken> {
  const row = getDb()
    .insert(apiTokens)
    .values({
      id: newId(),
      orgId: input.orgId,
      userId: input.userId,
      name: input.name,
      scope: input.scope,
      prefix: input.prefix,
      tokenHash: input.tokenHash,
      expiresAt: input.expiresAt,
      lastUsedAt: null,
      revokedAt: null,
      createdAt: input.createdAt,
    })
    .returning()
    .get();
  return toApiToken(row);
}

/** Tokens neither revoked nor expired at `now`. */
export async function countUsableTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ count: sql<number>`count(*)` })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .get();
  return row?.count ?? 0;
}

/** Every token of the user in the org, revoked and expired included, newest first. */
export async function listTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all()
    .map(toApiToken);
}

/** Tokens of the user in the org that have not been revoked yet. */
export async function listUnrevokedTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all()
    .map(toApiToken);
}

export async function findTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Global lookup: the secret itself identifies the tenant. */
export async function findTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Sets `revokedAt` unless already set; returns the stored row either way. */
export async function revokeToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .run();
  return findTokenById(orgId, tokenId);
}

export async function touchLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .run();
}
EOF
cat > src/server/services/api-token-service.ts <<'EOF'
/**
 * Personal API tokens: scripts and CI call Taskflow on a member's behalf.
 *
 * The secret (`tfk_…`) is returned once from `createApiToken`; only its
 * `hashToken()` digest is stored. Creations and revocations are published as
 * domain events and recorded by `ActivityService`.
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { envelope, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";
import type { PermissionAction } from "@/types/permission";

const TOKEN_PREFIX = "tfk_";
const PREFIX_LENGTH = 12;
const MAX_USABLE_TOKENS = 5;
const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * Token rules are finer than the role matrix (a viewer may create a `read`
 * token but not a `write` one), so the guard is expressed here and raises the
 * same error `assertCan()` would.
 */
function requireRole(
  actor: Actor,
  atLeast: Role,
  action: PermissionAction,
  orgId: OrgId,
): void {
  if (hasRoleAtLeast(actor.role, atLeast)) return;
  throw new PermissionDeniedError(action, {
    action,
    role: actor.role,
    resourceKind: orgResource(orgId).kind,
    allowed: false,
    reason: "denied_by_role",
  } as unknown as ConstructorParameters<typeof PermissionDeniedError>[1]);
}

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    requireRole(actor, "member", "org:update", parsed.orgId);
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const usable = await apiTokenRepo.countUsableTokens(
    parsed.orgId,
    actor.userId,
    createdAt,
  );
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      `A member may hold at most ${MAX_USABLE_TOKENS} active API tokens per organization`,
    );
  }

  const token = `${TOKEN_PREFIX}${randomToken()}`;
  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt: toIsoTimestamp(
      new Date(now.getTime() + parsed.expiresInDays * DAY_MS),
    ),
    createdAt,
  });

  await emit("api_token.created", {
    ...envelope(apiToken.orgId, actor.userId),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    requireRole(actor, "admin", "member:read", orgId);
  }
  return apiTokenRepo.listTokensForUser(orgId, userId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    requireRole(actor, "admin", "member:remove", orgId);
  }

  return revokeAndAudit(existing, actor.userId);
}

/** Resolves the `Actor` a presented secret acts as, or `null`. */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  if (typeof token !== "string" || !token.startsWith(TOKEN_PREFIX)) return null;

  const apiToken = await apiTokenRepo.findTokenByHash(hashToken(token));
  if (!apiToken || apiToken.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (!member || member.status !== "active" || member.archivedAt !== null) {
    return null;
  }

  await apiTokenRepo.touchLastUsed(apiToken.orgId, apiToken.id, now);

  return {
    userId: apiToken.userId,
    orgId: apiToken.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Revokes one token and publishes `api_token.revoked`. An already-revoked
 * token is returned unchanged and nothing is published.
 */
async function revokeAndAudit(
  token: ApiToken,
  actorId: UserId | null,
): Promise<ApiToken> {
  if (token.revokedAt !== null) return token;

  const revoked = requireFound(
    await apiTokenRepo.revokeToken(
      token.orgId,
      token.id,
