/**
 * Personal API tokens: scripts and CI call Taskflow on a member's behalf.
 *
 * The secret (`tfk_…`) is returned once from `createApiToken`; only its
 * `hashToken()` digest is stored. Creations and revocations are published as
 * domain events and recorded by `ActivityService`.
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { envelope, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";
import type { PermissionAction } from "@/types/permission";

const TOKEN_PREFIX = "tfk_";
const PREFIX_LENGTH = 12;
const MAX_USABLE_TOKENS = 5;
const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * Token rules are finer than the role matrix (a viewer may create a `read`
 * token but not a `write` one), so the guard is expressed here and raises the
 * same error `assertCan()` would.
 */
function requireRole(
  actor: Actor,
  atLeast: Role,
  action: PermissionAction,
  orgId: OrgId,
): void {
  if (hasRoleAtLeast(actor.role, atLeast)) return;
  throw new PermissionDeniedError(action, {
    action,
    role: actor.role,
    resourceKind: orgResource(orgId).kind,
    allowed: false,
    reason: "denied_by_role",
  } as unknown as ConstructorParameters<typeof PermissionDeniedError>[1]);
}

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    requireRole(actor, "member", "org:update", parsed.orgId);
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const usable = await apiTokenRepo.countUsableTokens(
    parsed.orgId,
    actor.userId,
    createdAt,
  );
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      `A member may hold at most ${MAX_USABLE_TOKENS} active API tokens per organization`,
    );
  }

  const token = `${TOKEN_PREFIX}${randomToken()}`;
  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt: toIsoTimestamp(
      new Date(now.getTime() + parsed.expiresInDays * DAY_MS),
    ),
    createdAt,
  });

  await emit("api_token.created", {
    ...envelope(apiToken.orgId, actor.userId),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    requireRole(actor, "admin", "member:read", orgId);
  }
  return apiTokenRepo.listTokensForUser(orgId, userId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    requireRole(actor, "admin", "member:remove", orgId);
  }

  return revokeAndAudit(existing, actor.userId);
}

/** Resolves the `Actor` a presented secret acts as, or `null`. */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  if (typeof token !== "string" || !token.startsWith(TOKEN_PREFIX)) return null;

  const apiToken = await apiTokenRepo.findTokenByHash(hashToken(token));
  if (!apiToken || apiToken.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (!member || member.status !== "active" || member.archivedAt !== null) {
    return null;
  }

  await apiTokenRepo.touchLastUsed(apiToken.orgId, apiToken.id, now);

  return {
    userId: apiToken.userId,
    orgId: apiToken.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Revokes one token and publishes `api_token.revoked`. An already-revoked
 * token is returned unchanged and nothing is published.
 */
async function revokeAndAudit(
  token: ApiToken,
  actorId: UserId | null,
): Promise<ApiToken> {
  if (token.revokedAt !== null) return token;

  const revoked = requireFound(
    await apiTokenRepo.revokeToken(
      token.orgId,
      token.id,
      toIsoTimestamp(new Date()),
    ),
    "ApiToken",
    token.id,
  );

  // A concurrent revocation won the race: its revokedAt stands, no second row.
  if (revoked.revokedAt !== null && token.revokedAt === null) {
    await emit("api_token.revoked", {
      ...envelope(revoked.orgId, actorId),
      tokenId: revoked.id,
      userId: revoked.userId,
      name: revoked.name,
    });
  }

  return revoked;
}

/**
 * A removed member's tokens in that organization stop working at once: every
 * one not already revoked is revoked, with the remover as actor.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listUnrevokedTokensForUser(
      payload.orgId,
      payload.userId,
    );
    for (const token of tokens) {
      await revokeAndAudit(token, payload.actorId);
    }
  });
}
