import { afterAll, beforeAll, expect, it } from "vitest";
import * as memberRepo from "@/server/repositories/member-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as svc from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => { unregisterEventHandlers(); cleanup(); });

it("works", async () => {
  const t = await createTenant("tok", "growth");
  const m = t.actors.member;
  const { token, apiToken } = await svc.createApiToken(m, { orgId: t.org.id, name: " ci ", scope: "write", expiresInDays: 3 });
  expect(token.startsWith("tfk_")).toBe(true);
  expect(apiToken.prefix).toBe(token.slice(0, 12));
  expect(apiToken.name).toBe("ci");
  await expect(svc.createApiToken(t.actors.viewer, { orgId: t.org.id, name: "x", scope: "write", expiresInDays: 3 })).rejects.toThrow();
  for (let i = 0; i < 4; i++) await svc.createApiToken(m, { orgId: t.org.id, name: "n" + i, scope: "read", expiresInDays: 3 });
  await expect(svc.createApiToken(m, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 3 })).rejects.toThrow();
  const list = await svc.listApiTokens(m, t.org.id);
  expect(list.map((x) => x.name)).toEqual(["n3", "n2", "n1", "n0", "ci"]);
  const a = await svc.authenticateApiToken(token);
  expect(a).toEqual({ userId: m.userId, orgId: t.org.id, role: "member" });
  const r = await svc.revokeApiToken(m, t.org.id, list[0]!.id);
  expect(r.revokedAt).not.toBeNull();
  const target = await memberRepo.findMember(t.org.id, m.userId);
  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: target!.id });
  expect(await svc.authenticateApiToken(token)).toBeNull();
  const acts = await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null } as never);
  const rows = acts.items.filter((e) => e.subjectKind === "api_token");
  console.log(rows.map((e) => `${e.action} ${e.actorId === t.actors.owner.userId ? "owner" : "member"}`));
  expect(rows.length).toBe(10);
});
EOF
